oxy_webhelp_navlinks = {"clone_lm_recovery_customization-d39307e39371":{"topics":[{"title":"Oracle initialization parameters","shortdesc":"<p class=\"shortdesc\">Information about required or recommended initialization parameters to specify when         you customize an Oracle database instance that is created during a recovery.<\/p>","href":"oracle\/oracle_initialization_parameters.html","attributes":{"data-id":"oracle_initialization_parameters"},"menu":{"hasChildren":false},"tocID":"oracle_initialization_parameters-d39307e39382","topics":[]},{"title":"Memory parameters","shortdesc":"<p class=\"shortdesc\">You can use memory parameters to account for differences in resource limitations         between the source and target hosts or Oracle RAC.<\/p>","href":"oracle\/clone_mount_memory_params.html","attributes":{"data-id":"clone_mount_memory_params"},"menu":{"hasChildren":false},"tocID":"clone_mount_memory_params-d39307e39393","topics":[]},{"title":"Clone and mount file location parameters","shortdesc":"<p class=\"shortdesc\">You can use file location parameters to account for differences in storage structures         between the source and target hosts or Oracle RAC.<\/p>","href":"oracle\/clone_mount_file_loc_params.html","attributes":{"data-id":"clone_mount_file_loc_params"},"menu":{"hasChildren":false},"tocID":"clone_mount_file_loc_params-d39307e39404","topics":[]},{"title":"Example of initialization parameters for customization","shortdesc":"<p class=\"shortdesc\">This example text file shows initialization parameters that you can specify to         customize the clone or live mount recovery of an Oracle database.<\/p>","href":"oracle\/example_initialization_parameters.html","attributes":{"data-id":"example_initialization_parameters"},"menu":{"hasChildren":false},"tocID":"example_initialization_parameters-d39307e39415","topics":[]}]}};